const tokenChecks = new Map();
function resolveBaseUrl() {
    const configured = process.env.FREEPI_BASE_URL?.trim();
    return (configured || DEFAULT_BASE_URL).replace(/\/+$/, "");
}
function completionsBaseUrl() {
    const base = resolveBaseUrl();
    return base.endsWith("/v1") ? base : `${base}/v1`;
}
function modelsRegistryUrl() {
    const configured = process.env.FREEPI_MODELS_URL?.trim() ||
        process.env.OPENCODE_MODELS_URL?.trim();
    return (configured || DEFAULT_MODELS_REGISTRY_URL).replace(/\/+$/, "");
}
function credentialsPath() {
    const override = process.env.FREEPI_CREDENTIALS_PATH?.trim();
    if (override)
        return resolve(override);
    return join(homedir(), ".free-pi", "agent", "credentials.json");
}
function credentialsDisplayPath() {
    const override = process.env.FREEPI_CREDENTIALS_PATH?.trim();
    if (override)
        return override;
    return process.platform === "win32"
        ? join("%USERPROFILE%", ".free-pi", "agent", "credentials.json")
        : "~/.free-pi/agent/credentials.json";
}
function normalizeIssuer(value) {
    if (typeof value !== "string")
        return undefined;
    try {
        const parsed = new URL(value);
        return parsed.protocol === "https:" || parsed.protocol === "http:"
            ? parsed.origin
            : undefined;
    }
    catch {
        return undefined;
    }
}
function safeUrl(value) {
    if (typeof value !== "string")
        return undefined;
    try {
        const parsed = new URL(value.trim());
        if (parsed.protocol !== "https:" && parsed.protocol !== "http:")
            return undefined;
        return parsed.toString();
    }
    catch {
        return undefined;
    }
}
function cleanText(value) {
    return typeof value === "string"
        ? value.replace(/[\u0000-\u001f\u007f-\u009f]/g, "").trim()
        : "";
}
async function readCredentials() {
    const envToken = process.env.FREEPI_JWT?.trim();
    if (envToken)
        return { token: envToken, issuer: resolveBaseUrl() };
    try {
        const raw = await readFile(credentialsPath(), "utf8");
        const parsed = JSON.parse(raw);
        if (typeof parsed.token !== "string" || parsed.token.length === 0)
            return undefined;
        const issuer = normalizeIssuer(parsed.issuer);
        return issuer ? { token: parsed.token, issuer } : { token: parsed.token };
    }
    catch {
        return undefined;
    }
}
async function readCredentialsToken() {
    return (await readCredentials())?.token;
}
async function writeCredentials(token, issuer) {
    const path = credentialsPath();
    const temporary = `${path}.${process.pid}.${Date.now()}.tmp`;
    const record = issuer
        ? { token, issuer: normalizeIssuer(issuer) ?? issuer }
        : { token };
    await mkdir(dirname(path), { recursive: true });
    await writeFile(temporary, JSON.stringify(record), { mode: 0o600 });
    try {
        await rename(temporary, path);
    }
    catch (error) {
        if (process.platform !== "win32")
            throw error;
        await rm(path, { force: true });
        await rename(temporary, path);
    }
}
function parseJwtClaims(token) {
    const payload = token.split(".")[1];
    if (!payload)
        return undefined;
    try {
        const parsed = JSON.parse(Buffer.from(payload, "base64url").toString("utf8"));
        return parsed && typeof parsed === "object"
            ? parsed
            : undefined;
    }
    catch {
        return undefined;
    }
}
function tokenExpiry(token) {
    const exp = parseJwtClaims(token)?.exp;
    return typeof exp === "number" && Number.isFinite(exp) && exp > 0
        ? exp * 1000
        : undefined;
}
function tokenNeedsRefresh(token, expires) {
    const now = Date.now();
    const jwtExpiry = tokenExpiry(token);
    return ((jwtExpiry !== undefined && jwtExpiry - now <= AUTH_SKEW_MS) ||
        (typeof expires === "number" &&
            expires > 0 &&
            expires - now <= AUTH_SKEW_MS));
}
function encodeRefreshToken(token, issuer) {
    const payload = JSON.stringify(issuer ? { token, issuer } : { token });
    return `${REFRESH_PREFIX}${Buffer.from(payload).toString("base64url")}`;
}
function decodeRefreshToken(value) {
    if (!value)
        return undefined;
    if (value.startsWith(REFRESH_PREFIX)) {
        try {
            const parsed = JSON.parse(Buffer.from(value.slice(REFRESH_PREFIX.length), "base64url").toString("utf8"));
            if (typeof parsed.token === "string" && parsed.token.length > 0) {
                const issuer = normalizeIssuer(parsed.issuer);
                return issuer
                    ? { token: parsed.token, issuer }
                    : { token: parsed.token };
            }
        }
        catch { }
    }
    try {
        const parsed = JSON.parse(value);
        if (typeof parsed.token === "string" && parsed.token.length > 0) {
            const issuer = normalizeIssuer(parsed.issuer);
            return issuer ? { token: parsed.token, issuer } : { token: parsed.token };
        }
    }
    catch { }
    return { token: value };
}
function tokenFromAuth(auth) {
    if (!auth)
        return undefined;
    if (auth.type === "oauth" && auth.access)
        return auth.access;
    if (auth.type === "api" && auth.key)
        return auth.key;
    if (auth.type === "wellknown" && auth.token)
        return auth.token;
    return undefined;
}
function expiryFromAuth(auth) {
    if (!auth)
        return undefined;
    if (auth.type === "oauth" && auth.expires > 0)
        return auth.expires;
    if (auth.type === "api" && auth.metadata?.expires) {
        const parsed = Number(auth.metadata.expires);
        if (Number.isFinite(parsed) && parsed > 0)
            return parsed;
    }
    const token = tokenFromAuth(auth);
    return token ? tokenExpiry(token) : undefined;
}
function issuerFromAuth(auth) {
    if (!auth)
        return undefined;
    if (auth.type === "oauth")
        return decodeRefreshToken(auth.refresh)?.issuer;
    if (auth.type === "api")
        return normalizeIssuer(auth.metadata?.issuer);
    return undefined;
}
async function persistToken(client, auth, token, issuer) {
    const expires = tokenExpiry(token) ?? Date.now() + DEFAULT_TOKEN_LIFETIME_MS;
    if (auth?.type === "api") {
        await client.auth.set({
            path: { id: PROVIDER_ID },
            body: {
                type: "api",
                key: token,
                metadata: {
                    ...(auth.metadata ?? {}),
                    ...(issuer ? { issuer } : {}),
                    expires: String(expires),
                },
            },
        });
        return;
    }
    await client.auth.set({
        path: { id: PROVIDER_ID },
        body: {
            type: "oauth",
            refresh: encodeRefreshToken(token, issuer),
            access: token,
            expires,
        },
    });
}
let lastExpiredToken;
async function resolveToken(client) {
    let auth;
    if (authResolver) {
        try {
            auth = await authResolver();
        }
        catch { }
    }
    const current = tokenFromAuth(auth);
    const stored = await readCredentials();
    if (current && !tokenNeedsRefresh(current, expiryFromAuth(auth)))
        return current;
    if (stored?.token &&
        stored.token !== current &&
        !tokenNeedsRefresh(stored.token)) {
        await persistToken(client, auth, stored.token, stored.issuer).catch(() => undefined);
        return stored.token;
    }
    if (current) {
        if (lastExpiredToken !== current) {
            lastExpiredToken = current;
            await client.app
                .log({
                body: {
                    service: "free-pi",
                    level: "warn",
                    message: "free-pi token is expired. free-pi does not expose a refresh endpoint; run `opencode auth login -p free-pi` to sign in again.",
                },
            })
                .catch(() => undefined);
        }
        return current;
    }
    return stored?.token;
}
function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
}
function duplicateNumber(value) {
    return typeof value === "number" && Number.isFinite(value) && value > 0
        ? value
        : undefined;
}
function deviceReport() {
    try {
