    credentialsAbort.abort();
    for (const registration of registrations.reverse()) {
      await registration.dispose?.().catch(() => undefined);
    }
    await hooks.dispose?.().catch(() => undefined);
  };
}

export default {
  id: PROVIDER_ID,
  setup: FreePiV2Setup,
  server: FreePiPlugin,
};
